-- Coaching
insert into public.programs (slug, name, type, status, tagline, summary, description, highlights, format_label,
  duration_label, catalog_group, draft_note, position, audience, meta)
values ('coaching', '1:1 Coaching with Mike', 'coaching', 'published', 'Your program, built around you', 'Direct coaching for people who want the program adapted to their body, schedule and goals — with feedback on technique and accountability week to week.', 'Direct coaching for people who want the program adapted to their body, schedule and goals — with feedback on technique and accountability week to week.

## How it works
Book a session in the app, send your training footage ahead of time, and spend the call working on exactly what is limiting you. Every session ends with a written plan.

- Video call with Mike, 60 or 90 minutes
- Technique review on your own footage
- A written block you can follow immediately
- Session notes and history kept in the app

## Who it is for
Lifters stuck at a plateau, people coming back from injury, and coaches who want their own coaching eye sharpened.

## Common questions
**Do I have to commit to a block?** No. Single sessions are fine, though most people book a four-session block.

**What if I need to move a session?** Reschedule from your coaching page up to 24 hours before.', array['Personal programming', 'Technique review', 'Weekly accountability']::text[],
  'Live video sessions', 'Weekly or fortnightly', 'experiences', null, 41, null, '{"schedule": {"weekdays": [2, 3, 4, 5, 6], "times": ["07:00", "08:00", "09:00", "10:00", "11:00", "13:00", "14:00"], "timezone": "America/Los_Angeles"}}'::jsonb)
